import json
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse

ROOT = Path(__file__).resolve().parent
LOCK = threading.Lock()
STATES = {}


def initial():
    return {'displayName': 'Alex', 'failNextSave': False, 'events': []}


class Handler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass

    def reply(self, status, body, content_type='application/json'):
        payload = body.encode() if isinstance(body, str) else json.dumps(body).encode()
        self.send_response(status)
        self.send_header('Content-Type', content_type)
        self.send_header('Content-Length', str(len(payload)))
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        self.wfile.write(payload)

    def do_GET(self):
        pieces = urlparse(self.path).path.strip('/').split('/')
        if pieces[0] == 'health':
            return self.reply(200, {'fixture': 'verify-ui-extension-v1', 'root': str(ROOT), 'ready': True})
        if pieces[0] not in ['baseline', 'candidate']:
            return self.reply(404, {'error': 'Unknown run'})
        run = pieces[0]
        route = '/'.join(pieces[1:])
        with LOCK:
            state = STATES.setdefault(run, initial())
            if route == 'api/preferences':
                state['events'].append({'method': 'GET', 'route': route})
                return self.reply(200, {'displayName': state['displayName']})
            if route == 'api/evidence':
                return self.reply(200, {'displayName': state['displayName'], 'events': state['events']})
        if route == 'styles.css':
            return self.reply(200, (ROOT / 'styles.css').read_text(), 'text/css')
        if route == 'app.js':
            return self.reply(200, (ROOT / 'app.js').read_text(), 'text/javascript')
        if route in ['', 'inbox', 'messages/alpha', 'messages/beta']:
            return self.reply(200, (ROOT / 'index.html').read_text().replace('__RUN__', run), 'text/html')
        return self.reply(404, {'error': 'Route not found'})

    def do_POST(self):
        pieces = urlparse(self.path).path.strip('/').split('/')
        if pieces[0] not in ['baseline', 'candidate']:
            return self.reply(404, {'error': 'Unknown run'})
        run = pieces[0]
        route = '/'.join(pieces[1:])
        try:
            body = json.loads(self.rfile.read(int(self.headers.get('Content-Length', '0'))) or b'{}')
        except ValueError:
            return self.reply(400, {'error': 'Invalid JSON'})
        with LOCK:
            state = STATES.setdefault(run, initial())
            if route == 'control/reset':
                STATES[run] = initial()
                return self.reply(200, {'reset': True})
            if route == 'control/fail-next-save':
                state['failNextSave'] = True
                state['events'].append({'method': 'POST', 'route': route})
                return self.reply(200, {'armed': True})
            if route == 'api/preferences':
                failed = state.pop('failNextSave', False)
                state['failNextSave'] = False
                status = 503 if failed else 200
                state['events'].append({'method': 'POST', 'route': route, 'status': status, 'displayName': body.get('displayName')})
                if failed:
                    return self.reply(status, {'error': 'Temporarily unavailable'})
                state['displayName'] = body.get('displayName', '')
                return self.reply(200, {'displayName': state['displayName']})
        return self.reply(404, {'error': 'Route not found'})


server = ThreadingHTTPServer(('127.0.0.1', 0), Handler)
(ROOT / 'server.json').write_text(json.dumps({'port': server.server_address[1], 'root': str(ROOT)}))
print(json.dumps({'port': server.server_address[1], 'fixture': 'verify-ui-extension-v1'}), flush=True)
server.serve_forever()

