'use strict';
const run = document.body.dataset.run;
const base = `/${run}`;
const editor = document.querySelector('#editor');
const nameInput = document.querySelector('#display-name');
const error = document.querySelector('#error');
const saved = document.querySelector('#saved');
const retry = document.querySelector('#retry');
const save = document.querySelector('#save');
async function refreshName() {
  const response = await fetch(`${base}/api/preferences`);
  const data = await response.json();
  document.querySelector('#welcome').textContent = `Welcome, ${data.displayName}`;
  if (!editor.open) nameInput.value = data.displayName;
}
document.querySelector('#edit').addEventListener('click', () => {
  error.hidden = true;
  saved.hidden = true;
  retry.hidden = true;
  editor.showModal();
});
document.querySelector('#close').addEventListener('click', () => editor.close());
document.querySelector('#profile-form').addEventListener('submit', async event => {
  event.preventDefault();
  save.disabled = true;
  error.hidden = true;
  saved.hidden = true;
  try {
    const response = await fetch(`${base}/api/preferences`, {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({displayName: nameInput.value})});
    if (!response.ok) throw new Error(`Save returned ${response.status}`);
    saved.hidden = false;
    retry.hidden = true;
    await refreshName();
  } catch {
    error.hidden = false;
    retry.hidden = false;
  } finally {
    save.disabled = false;
  }
});
retry.addEventListener('click', () => {
  error.hidden = true;
  saved.hidden = false;
  retry.hidden = true;
});
document.querySelector('#theme').addEventListener('click', event => {
  const theme = document.documentElement.dataset.theme === 'light' ? 'dark' : 'light';
  document.documentElement.dataset.theme = theme;
  event.target.textContent = theme === 'light' ? 'Switch to dark' : 'Switch to light';
});
const messageId = location.pathname.split('/').pop();
if (messageId === 'alpha' || messageId === 'beta') {
  document.querySelector('#inbox').hidden = true;
  document.querySelector('#message').hidden = false;
  const title = document.querySelector('#message-title');
  title.textContent = messageId === 'alpha' ? 'Launch notes' : 'Budget decision';
  document.querySelector('#message-body').textContent = messageId === 'alpha' ? 'The launch review is on Tuesday.' : 'The team budget has been approved.';
  title.focus();
}
refreshName();

